from __future__ import annotations

import os
import platform
import subprocess
from pathlib import PurePosixPath, PureWindowsPath
from typing import Callable

from secretscan.model import Finding, Module, ModuleStatus
from secretscan.rules.rule import CompiledRule
from secretscan.scanner.content import scan_lines


def _get_own_pids_unix() -> list[str]:
    uid = os.getuid()
    try:
        result = subprocess.run(
            ["ps", "-eo", "pid=,uid="],
            capture_output=True, text=True, timeout=10,
        )
    except (subprocess.SubprocessError, FileNotFoundError):
        return []

    pids: list[str] = []
    for line in result.stdout.splitlines():
        fields = line.split()
        if len(fields) != 2:
            continue
        try:
            if int(fields[1]) == uid:
                pids.append(fields[0])
        except ValueError:
            continue
    return pids


def _get_cmdline_unix(pid: str) -> str:
    try:
        out = subprocess.run(
            ["ps", "-ww", "-o", "command=", "-p", pid, "-E"],
            capture_output=True, text=True, timeout=5,
        )
        return out.stdout.strip()
    except (subprocess.SubprocessError, FileNotFoundError):
        return ""


def _get_own_processes_windows() -> list[tuple[str, str]]:
    try:
        result = subprocess.run(
            ["wmic", "process", "where",
             f"SessionId={os.getpid()}", "get",
             "ProcessId,CommandLine", "/format:csv"],
            capture_output=True, text=True, timeout=15,
        )
        if result.returncode != 0:
            return []
    except (subprocess.SubprocessError, FileNotFoundError):
        return []

    processes: list[tuple[str, str]] = []
    for line in result.stdout.strip().splitlines()[1:]:
        parts = line.strip().split(",")
        if len(parts) < 3:
            continue
        cmdline = ",".join(parts[1:-1])
        pid = parts[-1]
        if cmdline.strip():
            processes.append((pid, cmdline.strip()))
    return processes


def process_env_scan(
    rules: list[CompiledRule],
    emit: Callable[[Finding], None],
    reveal_length: bool = False,
    allow_matcher: Callable[[str], bool] | None = None,
) -> ModuleStatus:
    status = ModuleStatus(module=Module.PROCESS_ENV)

    system = platform.system()

    if system == "Windows":
        processes = _get_own_processes_windows()
        status.attempted = len(processes)

        for pid, cmdline in processes:
            status.accessed += 1
            findings: list[Finding] = []

            def capture(f: Finding, _pid=pid, _cmd=cmdline) -> None:
                f.pid = _pid
                f.process_name = PureWindowsPath(_cmd.split()[0]).name if _cmd.split() else ""
                findings.append(f)

            scan_lines(
                [cmdline], rules, f"pid {pid}", Module.PROCESS_ENV, capture,
                reveal_length=reveal_length, allow_matcher=allow_matcher,
            )
            for f in findings:
                emit(f)
    else:
        own_pids = _get_own_pids_unix()
        status.attempted = len(own_pids)

        for pid in own_pids:
            cmdline = _get_cmdline_unix(pid)
            if not cmdline:
                status.skipped += 1
                continue

            status.accessed += 1
            findings = []

            def capture(f: Finding, _pid=pid, _cmd=cmdline) -> None:
                f.pid = _pid
                f.process_name = PurePosixPath(_cmd.split()[0]).name if _cmd.split() else ""
                findings.append(f)

            scan_lines(
                [cmdline], rules, f"pid {pid}", Module.PROCESS_ENV, capture,
                reveal_length=reveal_length, allow_matcher=allow_matcher,
            )
            for f in findings:
                emit(f)

    status.note = (
        "only the current user's own processes are inspected; "
        "OS-level restrictions may limit env visibility, "
        "so a low accessed count is expected"
    )
    return status
